from pathlib import Path
import json

TARGET = 'DEV-PRED-HENGELTJE-AUTOBUILD-20260930-E001'
HOME = Path.home()
ROOTS = {
    'command_bus_state': HOME / '.local/state/prediction-command-bus',
    'project_executor_state': HOME / '.local/state/prediction-project-executor',
    'project_executor_worktrees': HOME / '.local/share/prediction-project-executor/worktrees',
}

def safe_text(p: Path) -> str:
    try:
        if p.stat().st_size > 2_000_000:
            return ''
        return p.read_text(encoding='utf-8', errors='replace')
    except Exception:
        return ''

def summarize_json(text: str):
    try:
        obj = json.loads(text)
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    keep = {}
    for k in ('task_id','status','state','result','exit_code','error','error_class','detail','created_at','started_at','finished_at','remote_commit','source_commit','worktree','branch'):
        if k in obj:
            v = obj[k]
            if isinstance(v, (dict,list)):
                v = str(v)[:1200]
            keep[k] = v
    return keep

print('HENGELTJE_E001_DIAG_BEGIN')
found_any = False
for label, root in ROOTS.items():
    print(f'ROOT {label} exists={root.exists()} path={root}')
    if not root.exists():
        continue
    matches = []
    try:
        paths = list(root.rglob('*'))
    except Exception as exc:
        print(f'ROOT_SCAN_ERROR {label} {type(exc).__name__}')
        continue
    for p in paths:
        try:
            if not p.is_file():
                continue
        except Exception:
            continue
        name_hit = TARGET in p.name
        text = safe_text(p)
        body_hit = TARGET in text
        if name_hit or body_hit:
            found_any = True
            rel = str(p)
            summary = summarize_json(text)
            matches.append((rel, summary, text[-1500:] if summary is None else ''))
    print(f'MATCH_COUNT {label} {len(matches)}')
    for rel, summary, tail in matches[:20]:
        print('MATCH_FILE', rel)
        if summary is not None:
            print('MATCH_JSON', json.dumps(summary, ensure_ascii=False, sort_keys=True))
        elif tail:
            compact = ' '.join(tail.split())
            print('MATCH_TAIL', compact[:1500])

wt = ROOTS['project_executor_worktrees'] / TARGET
print('TARGET_WORKTREE_EXISTS=' + ('YES' if wt.exists() else 'NO'))
if wt.exists():
    gitfile = wt / '.git'
    print('TARGET_WORKTREE_GIT_POINTER=' + safe_text(gitfile).strip()[:500])

cb_tasks = ROOTS['command_bus_state'] / 'tasks'
if cb_tasks.exists():
    direct = list(cb_tasks.glob('*' + TARGET + '*'))
    print('DIRECT_COMMAND_BUS_TASK_FILES=' + str(len(direct)))
    for p in direct[:20]:
        print('DIRECT_CB_FILE', p)
        txt = safe_text(p)
        summary = summarize_json(txt)
        if summary is not None:
            print('DIRECT_CB_JSON', json.dumps(summary, ensure_ascii=False, sort_keys=True))

print('TARGET_FOUND_ANYWHERE=' + ('YES' if found_any else 'NO'))
print('NO_LIVE_TRADING=YES')
print('NO_PAID_ACTIONS=YES')
print('NO_WALLET_ACTIONS=YES')
print('NO_REMOTE_PUSH=YES')
print('HENGELTJE_E001_DIAG_END')
